from solution import cycpattern_check
import pytest
from hypothesis import given
import hypothesis.strategies as st


def _rotations(s):
    if len(s) == 0:
        return [""]
    return [s[i:] + s[:i] for i in range(len(s))]


def _reference(a, b):
    if b == "":
        return True
    for r in _rotations(b):
        if r in a:
            return True
    return False


def test_examples_abcd_abd():
    assert cycpattern_check("abcd", "abd") is False


def test_examples_hello_ell():
    assert cycpattern_check("hello", "ell") is True


def test_examples_whassup_psus():
    assert cycpattern_check("whassup", "psus") is False


def test_examples_abab_baa():
    assert cycpattern_check("abab", "baa") is True


def test_examples_efef_eeff():
    assert cycpattern_check("efef", "eeff") is False


def test_examples_himenss_simen():
    assert cycpattern_check("himenss", "simen") is True


def test_empty_b_is_vacuously_substring():
    assert cycpattern_check("abc", "") is True


def test_empty_both_is_true():
    assert cycpattern_check("", "") is True


def test_empty_a_nonempty_b_is_false():
    assert cycpattern_check("", "a") is False
    assert cycpattern_check("", "abc") is False


@given(st.text(alphabet="abc", min_size=0, max_size=6), st.text(alphabet="abc", min_size=0, max_size=4))
def test_reference_equivalence(a, b):
    assert cycpattern_check(a, b) == _reference(a, b)


@given(st.text(alphabet="ab", min_size=1, max_size=6), st.text(alphabet="ab", min_size=1, max_size=4))
def test_rotation_invariance(a, b):
    k = 1 if len(b) == 1 else 2
    if len(b) <= 1:
        rot = b
    else:
        rot = b[k % len(b):] + b[:k % len(b)]
    assert cycpattern_check(a, b) == cycpattern_check(a, rot)


@given(st.text(alphabet="abc", min_size=0, max_size=6), st.text(alphabet="abc", min_size=1, max_size=4))
def test_substring_of_a_implies_true(a, b):
    if b in a:
        assert cycpattern_check(a, b) is True


@given(st.text(alphabet="abc", min_size=0, max_size=5), st.text(alphabet="abc", min_size=1, max_size=5))
def test_longer_b_cannot_match(a, b):
    if len(b) > len(a):
        assert cycpattern_check(a, b) is False


@given(
    st.text(alphabet="ab", min_size=0, max_size=5),
    st.text(alphabet="ab", min_size=0, max_size=3),
    st.text(alphabet="ab", min_size=0, max_size=3),
    st.text(alphabet="ab", min_size=1, max_size=3),
)
def test_extension_monotonicity(a, pre, suf, b):
    if cycpattern_check(a, b) is True:
        assert cycpattern_check(pre + a + suf, b) is True


@given(st.text(alphabet="abc", min_size=0, max_size=6), st.text(alphabet="abc", min_size=1, max_size=1))
def test_single_char_matches_membership(a, b):
    assert cycpattern_check(a, b) == (b in a)


@given(st.text(alphabet="abc", min_size=0, max_size=6), st.text(alphabet="abc", min_size=1, max_size=4))
def test_double_string_model(a, b):
    doubled = b + b
    expected = any(
        len(a) >= len(b)
        and a[i:i + len(b)] in doubled
        and len(a[i:i + len(b)]) == len(b)
        and a[i:i + len(b)] != ""
        or (len(b) == 1 and a[i:i + len(b)] in doubled)
        for i in range(max(0, len(a) - len(b) + 1))
    )
    # simpler direct check: exists window of a that appears in b+b
    found = False
    for i in range(max(0, len(a) - len(b) + 1)):
        window = a[i:i + len(b)]
        if window in doubled:
            found = True
            break
    assert cycpattern_check(a, b) == found
